#!/usr/bin/env python3
"""GitHub-free public beta packaging; builds on the verified v0.5 catalog."""
from pathlib import Path
import subprocess,sys,json,os
from html import escape
ROOT=Path(__file__).resolve().parent
subprocess.run([sys.executable,str(ROOT/'build_v05.py')],cwd=ROOT,check=True)
SITE=ROOT/'site'
# Keep v0.5 as deterministic source; add a collection-independent fan submission workflow.
contribute=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Source-backed corrections and research leads for The Jam Archive. Export a contribution without an account."><title>Contribute research · The Jam Archive</title><link rel="stylesheet" href="../assets/detail.css"><style>
.form-card{display:grid;gap:14px}.form-card label{display:grid;gap:6px;font-size:14px;font-weight:700}.form-card input,.form-card select,.form-card textarea{width:100%;background:#142424;color:#e8eddb;border:1px solid #51716b;padding:12px;border-radius:8px;font:inherit}.form-card textarea{min-height:125px;resize:vertical}.hint{color:#a5b8b1;font-size:12px}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.actions button{background:#cff08e;color:#122015;padding:12px 17px;border-radius:8px;font-weight:750;border:0;cursor:pointer}.actions button.secondary{background:#253833;color:#cff08e;border:1px solid #60846d}.feedback{min-height:24px;color:#cff08e}label input:focus-visible,label textarea:focus-visible{outline:2px solid #cff08e;outline-offset:2px}.warning{padding:12px 15px;border:1px solid #7c6850;background:#392e23;border-radius:8px;color:#f3d1a4}
</style></head><body><header><a href="../index.html">THE <span>JAM</span> ARCHIVE</a><nav><a href="../index.html">Discover</a><a href="../research-gaps/index.html">Research gaps</a><a href="../about/index.html">About</a></nav></header><main><div class="eyebrow">COMMUNITY RESEARCH / EVIDENCE FIRST</div><h1>Help improve the archive.</h1><p class="lead">Share a correction, recording lead, collaborator, or missing show. We retain original source attribution and never treat unverified submissions as fact.</p>
<div class="warning"><b>This form is offline-only.</b> It prepares a structured JSON file <em>on your device</em>. It does not send anything to The Jam Archive. A public submission address or moderation service has not yet been established. Please retain the exported file for submission once that channel is announced.</div>
<div class="cols"><section class="card"><h2>Prepare a research contribution</h2><form id="contribution" class="form-card">
<label>What are you contributing?<select name="kind" required><option value="show_correction">Historical show / setlist correction</option><option value="recording_source">Recording / tape lineage lead</option><option value="musician_relationship">Musician / project / sit-in evidence</option><option value="tour_announcement">Tour or reunion announcement</option><option value="broken_link">Broken or outdated archive link</option><option value="other">Other archive research</option></select></label>
<label>Artist, project, or performance<input name="subject" maxlength="160" required placeholder="e.g. The Allman Brothers Band — March 12, 1971 late set"></label>
<label>Show date (optional)<input type="date" name="date"></label>
<label>Original source URL (required)<input name="source_url" type="url" required maxlength="1000" placeholder="https://..." pattern="https://.*" title="Use an https:// link to the original source"></label>
<label>Evidence and proposed correction<textarea name="details" minlength="20" maxlength="5000" required placeholder="What should be added or corrected? What exactly does the source establish? Note uncertainties and source lineage."></textarea></label>
<label>Attribution / credit (optional)<input name="credit" maxlength="120" placeholder="Public credit name or anonymous — avoid private information"></label>
<p class="hint">Please do not include personal addresses, private contact details, copyrighted audio, paywalled material, or unlicensed photographs. A source link is not permission to redistribute content.</p>
<div class="actions"><button type="submit">Download submission JSON</button><button type="button" class="secondary" id="copy-submission">Copy summary</button></div><div id="feedback" class="feedback" aria-live="polite"></div>
</form></section><aside><div class="card"><h2>How we'll review it</h2><ol><li>Identify the original source and its custodian.</li><li>Check dates, lineups, early/late sets, and provenance.</li><li>Compare against existing records for duplicates.</li><li>Mark uncertain claims for further research.</li><li>Publish only after evidence review, with attribution.</li></ol></div><div class="card"><h2>Find a useful task</h2><p>Explore missing recording pointers and musician connections that still need verification.</p><a class="button" href="../research-gaps/index.html">Explore research gaps →</a></div></aside></div>
<footer>No user accounts or data collection. The generated contribution file stays on your device until you choose to share it. Fan-built · Source-first · Unofficial.</footer></main>
<script>
(()=>{'use strict';const f=document.getElementById('contribution'),status=document.getElementById('feedback');function payload(){const d=new FormData(f),url=String(d.get('source_url')||'').trim();if(!/^https:\/\/[^\s/]+/.test(url))throw Error('Supply an https:// source URL.');const details=String(d.get('details')||'').trim(),subject=String(d.get('subject')||'').trim();if(subject.length<2||details.length<20)throw Error('Provide the subject and at least 20 characters of evidence.');return {schema:'jam-archive-contribution-v1',kind:String(d.get('kind')),subject,date:String(d.get('date')||''),source_url:url,details,credit:String(d.get('credit')||'').trim(),status:'pending_review',submitted_at:new Date().toISOString(),notice:'Research lead only. Must be verified before publication.'};}function safeName(x){return String(x).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,55)||'research'}f.addEventListener('submit',e=>{e.preventDefault();try{const p=payload(),a=document.createElement('a'),b=new Blob([JSON.stringify(p,null,2)+'\n'],{type:'application/json'});a.href=URL.createObjectURL(b);a.download='jam-archive-'+safeName(p.subject)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);status.textContent='JSON prepared and downloaded. Nothing was transmitted.';}catch(e){status.textContent=e.message;}});document.getElementById('copy-submission').addEventListener('click',async()=>{try{const p=payload(),txt=[p.kind,p.subject,p.date,'Source: '+p.source_url,p.details,p.credit].filter(Boolean).join('\n');await navigator.clipboard.writeText(txt);status.textContent='Research summary copied locally.';}catch(e){status.textContent=e.message+' If clipboard access is blocked, use Download submission JSON.';}});})();
</script></body></html>'''
(SITE/'contribute/index.html').write_text(contribute,encoding='utf-8')
about='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>About and editorial standards · The Jam Archive</title><meta name="description" content="The Jam Archive's mission, reliability standards, data rights and limitations."><link rel="stylesheet" href="../assets/detail.css"></head><body><header><a href="../index.html">THE <span>JAM</span> ARCHIVE</a><nav><a href="../index.html">Discover</a><a href="../trails/index.html">Listening trails</a><a href="../contribute/index.html">Contribute</a></nav></header><main><div class="eyebrow">FREE / FAN-BUILT / SOURCE-FIRST</div><h1>Music is a living history.</h1><p class="lead">The Jam Archive connects live performances, bands, individual musicians, original recordings, and the communities that document them. Our purpose is discovery and preservation—not replacing existing fan archives or controlling the music.</p><div class="card"><h2>Editorial standards</h2><ul><li><b>Evidence:</b> Every factual claim should trace to an identifiable source. Direct documentation is preferred over speculation.</li><li><b>Recordings:</b> A concert can have multiple distinct tapes, transfers, mixes, and official releases. We don't combine them into a single generic file.</li><li><b>Separate sets:</b> Early/late sets are distinct when evidence supports the distinction.</li><li><b>Uncertainty:</b> Historical memberships do not imply a specific sit-in. Unverified leads remain labeled.</li><li><b>Attribution:</b> Original taper, archive, researcher and rightsholder credits should be preserved.</li><li><b>Corrections:</b> Changes need evidence and a review process; they should not silently overwrite archival history.</li></ul></div><div class="card"><h2>What's here today</h2><p>196 artist/project entries, 9 hand-curated historical show dossiers, 9 recording-source references, 32 song-title indexes, and 45 published concert entries in a <b>static October 26, 2026 snapshot</b>. Coverage is intentionally incomplete; future events are not refreshed automatically and no ticket availability is guaranteed.</p><p>The research engine is an offline developer tool, not a continuously running public agent. The site doesn't redistribute concert audio.</p></div><div class="card"><h2>Rights and privacy</h2><p>External source links do not convey ownership or redistribution permission. Site maintainers should review each data source's use conditions before import or republishing. Artist names are used descriptively; the archive is independent and unofficial.</p><p>Followed artists and listening journals are stored in your browser, not in our servers. The static site's contribution tool downloads a JSON file locally; it does not send contributions to us. An eventual hosting provider may process ordinary web access logs under its own terms.</p></div><div class="card"><h2>Join the work</h2><p>Archive gaps and corrections are opportunities for knowledgeable fans to help. Research contributions are locally exportable now; a submission channel is still being established.</p><a class="button" href="../contribute/index.html">Prepare a research contribution →</a></div><footer>Independent · No registration · No paywall · No hosted recordings.</footer></main></body></html>'''
(SITE/'about').mkdir(exist_ok=True)
(SITE/'about/index.html').write_text(about,encoding='utf-8')
# Keep version indicator and add navigable public standards and research forms.
index=(SITE/'index.html').read_text(encoding='utf-8')
index=index.replace('PUBLIC DISCOVERY EDITION · v0.5','PUBLIC BETA · v0.6').replace('THE JAM ARCHIVE · v0.5','THE JAM ARCHIVE · v0.6')
index=index.replace('Data checked October 26, 2026.<br>Automated collection requires a configured runner. No email alerts yet.', 'Data checked October 26, 2026.<br>Automated collection requires a configured runner. No email alerts yet.<br><br><a href="about/index.html">About &amp; editorial standards →</a><br><a href="contribute/index.html">Contribute research →</a>')
(SITE/'index.html').write_text(index,encoding='utf-8')
# Portable no-server preview mirrors the v0.6 homepage and points deep links at site/.
standalone=index.replace('<script src="assets/discovery.js"></script>', '<script>'+ (ROOT/'discovery_ui.js').read_text(encoding='utf-8') + '</script>')
standalone=standalone.replace('<head>', '<head><base href="site/">',1)
(ROOT/'standalone_preview.html').write_text(standalone,encoding='utf-8')
# Give all generated dossier pages a permanent route to transparent standards.
for path in [*SITE.glob('artists/*/index.html'),*SITE.glob('shows/*/index.html'),*SITE.glob('songs/*/index.html'),*SITE.glob('trails/*/index.html')]:
    txt=path.read_text(encoding='utf-8')
    txt=txt.replace('<a href="../../contribute/index.html">Contribute</a>', '<a href="../../contribute/index.html">Contribute</a><a href="../../about/index.html">About</a>')
    path.write_text(txt,encoding='utf-8')
# Site index files in other folders have different relative roots.
for path in [SITE/'trails/index.html',SITE/'research-gaps/index.html']:
    txt=path.read_text(encoding='utf-8')
    txt=txt.replace('<a href="../contribute/index.html">Contribute</a>', '<a href="../contribute/index.html">Contribute</a><a href="../about/index.html">About</a>')
    path.write_text(txt,encoding='utf-8')
# Deployment metadata updated without claiming sitemap until the origin is known.
origin=os.environ.get('JAM_ARCHIVE_ORIGIN','').strip().rstrip('/')
if origin and (SITE/'sitemap.xml').exists():
    sitemap=(SITE/'sitemap.xml').read_text(encoding='utf-8')
    sitemap=sitemap.replace('</urlset>',f'<url><loc>{escape(origin)}/about/</loc></url></urlset>')
    (SITE/'sitemap.xml').write_text(sitemap,encoding='utf-8')
report=json.loads((SITE/'assets/build_report.json').read_text(encoding='utf-8'))
report['version']='0.6';report['offline_contribution_tool']=True;report['github_free_deployment']=True;report['site_files']=sum(f.is_file() for f in SITE.rglob('*'))
(SITE/'assets/build_report.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print(f'v0.6: {report["site_files"]} public files, about page and offline correction intake prepared')
